package com.example

import com.example.ExamQuestionHelper.QSpec

/**
 * Domain 0: සිතියම් කියවීම, පරිමාණ හා භූගෝලීය තොරතුරු
 * (Topographic Maps, Scales, Contours, Grid References, GIS, GPS & Remote Sensing)
 * Strictly unique, non-repetitive MCQs with 4 authentic Sinhala options each.
 */
internal object GeographyLiveExamMapsBank {

  private fun q(t: String, s: String, c: String, d1: String, d2: String, d3: String, e: String) =
    QSpec(t, s, c, listOf(d1, d2, d3), e)

  fun mapQuestions(): List<QSpec> {
    val t = "සිතියම් කියවීම, පරිමාණ හා භූගෝලීය තොරතුරු"
    return listOf(
      q(t, "ශ්‍රී ලංකාවේ මිනින්දෝරු දෙපාර්තමේන්තුව මඟින් ප්‍රකාශයට පත් කරන සම්මත භූලක්ෂණ සිතියම් මාලාවේ පරිමාණය කුමක්ද?",
        "1:50,000 මෙට්‍රික් භූලක්ෂණ සිතියම් මාලාව", "1:63,360 අඟලට සැතපුම් සිතියම් මාලාව", "1:250,000 පළාත් පරිපාලන සිතියම් මාලාව", "1:1,000,000 ජාතික සිතියම් පොත් මාලාව",
        "පැරණි අඟල් 1 සැතපුම් (1:63,360) සිතියම් වෙනුවට වර්තමානයේ 1:50,000 මෙට්‍රික් සිතියම් භාවිත කෙරේ."),
      q(t, "1:50,000 භූලක්ෂණ සිතියමක සෙ.මී. 1 කින් නිරූපණය වන සැබෑ භූමි දුර කොපමණද?",
        "භූමියේ මීටර් 500 හෙවත් කිලෝමීටර් 0.5 ක්", "භූමියේ මීටර් 50 හෙවත් කිලෝමීටර් 0.05 ක්", "භූමියේ මීටර් 2,500 හෙවත් කිලෝමීටර් 2.5 ක්", "භූමියේ මීටර් 5,000 හෙවත් කිලෝමීටර් 5.0 ක්",
        "1:50,000 යනු සිතියමේ 1 cm = බිමෙහි 50,000 cm = 500 m = 0.5 km යන්නයි."),
      q(t, "ශ්‍රී ලංකාවේ මුළු භූමි ප්‍රමාණය ආවරණය කිරීම සඳහා සකස් කර ඇති 1:50,000 භූලක්ෂණ සිතියම් පත්‍ර සංඛ්‍යාව කීයද?",
        "දිවයිනම ආවරණය වන සිතියම් පත්‍ර 92 කි", "දිවයිනම ආවරණය වන සිතියම් පත්‍ර 25 කි", "දිවයිනම ආවරණය වන සිතියම් පත්‍ර 50 කි", "දිවයිනම ආවරණය වන සිතියම් පත්‍ර 150 කි",
        "දිවයින පුරා 1:50,000 මෙට්‍රික් භූලක්ෂණ සිතියම් පත්‍ර 92 ක් මිනින්දෝරු දෙපාර්තමේන්තුව විසින් ප්‍රකාශයට පත් කර ඇත."),
      q(t, "පැරණි ශ්‍රී ලංකා අඟල් එකේ භූලක්ෂණ සිතියම්වල (One-Inch Maps) නිරූපණ භාග පරිමාණය කුමක්ද?",
        "1:63,360 අනුපාත පරිමාණය", "1:50,000 අනුපාත පරිමාණය", "1:25,000 අනුපාත පරිමාණය", "1:100,000 අනුපාත පරිමාණය",
        "සැතපුම් 1 ක් අඟල් 63,360 ක් වන බැවින් අඟලට සැතපුම පරිමාණය 1:63,360 ලෙස දැක්වේ."),
      q(t, "'1:25,000' ලෙස දැක්වෙන පරිමාණ ප්‍රකාශන ක්‍රමය සිතියම් විද්‍යාවේදී හඳුන්වන්නේ කුමන නමින්ද?",
        "නිරූපණ භාග පරිමාණය (Representative Fraction)", "ප්‍රකාශිත පරිමාණය (Statement Scale)", "රේඛීය පරිමාණය (Linear Scale)", "චිත්‍රක පරිමාණය (Graphic Scale)",
        "ඕනෑම මිනුම් ඒකකයකින් කියවිය හැකි අනුපාත ආකාරය නිරූපණ භාගය (RF) නම් වේ."),
      q(t, "සිතියමක් ඡායාපිටපත් කිරීමේදී හෝ විශාලනය/කුඩා කිරීමේදී පවා නිවැරදි මිනුම් ලබා ගැනීමට වඩාත් උචිත පරිමාණ වර්ගය කුමක්ද?",
        "සිතියමේ අඳින ලද රේඛීය පරිමාණය", "වචනවලින් ලියූ ප්‍රකාශිත පරිමාණය", "සංඛ්‍යාත්මක නිරූපණ භාග පරිමාණය", "ඛණ්ඩාංක පාදක අක්ෂාංශ පරිමාණය",
        "රේඛීය පරිමාණය සිතියම සමඟ සමානුපාතිකව විශාල හෝ කුඩා වන බැවින් මිනුම් වරදින්නේ නැත."),
      q(t, "'සෙ.මී. 2 ට කි.මී. 1 කි' යන ප්‍රකාශිත පරිමාණයේ නිරූපණ භාගය (RF) කුමක්ද?",
        "1:50,000 නිරූපණ භාගය", "1:20,000 නිරූපණ භාගය", "1:100,000 නිරූපණ භාගය", "1:200,000 නිරූපණ භාගය",
        "2 cm = 1 km = 100,000 cm බැවින් 1 cm = 50,000 cm හෙවත් 1:50,000 වේ."),
      q(t, "1:10,000 සහ 1:1,000,000 යන සිතියම් දෙක සැසඳීමේදී 'විශාල පරිමාණ සිතියම' (Large Scale Map) කුමක්ද?",
        "කුඩා හරයක් ඇති 1:10,000 සිතියම", "විශාල හරයක් ඇති 1:1,000,000 සිතියම", "පරිමාණ දෙකම එකම විශාලත්වයෙන් යුක්තය", "සිතියම් වර්ගය නොදැන තීරණය කළ නොහැකිය",
        "භාගයක හරය කුඩා වන තරමට පරිමාණය විශාල වන අතර කුඩා ප්‍රදේශයක වැඩි විස්තර පෙන්වයි."),
      q(t, "නගර සැලසුමක් හෝ ගොඩනැගිලි භූමි සැලැස්මක් ඇඳීම සඳහා වඩාත් සුදුසු වන්නේ කුමන ආකාරයේ සිතියමක්ද?",
        "සවිස්තර තොරතුරු දැක්වෙන විශාල පරිමාණ සිතියම්", "මහාද්වීප පෙන්වන කුඩා පරිමාණ ලෝක සිතියම්", "රටවල් සීමා දැක්වෙන සිතියම් පොත් සිතියම්", "ගෝලීය උෂ්ණත්වය පෙන්වන දේශගුණ කලාප සිතියම්",
        "විශාල පරිමාණ සිතියම් මඟින් කුඩා ප්‍රදේශයක මංමාවත්, ගොඩනැගිලි ආදී සියුම් තොරතුරු දැක්වේ."),
      q(t, "ශ්‍රී ලංකාවේ 1:50,000 භූලක්ෂණ සිතියමක සම්මත සමෝච්ච රේඛා පරතරය (Contour Interval) මීටර් කීයද?",
        "මීටර් 20 ක ස්ථිර උන්නතාංශ පරතරයකි", "මීටර් 5 ක ස්ථිර උන්නතාංශ පරතරයකි", "මීටර් 50 ක ස්ථිර උන්නතාංශ පරතරයකි", "මීටර් 100 ක ස්ථිර උන්නතාංශ පරතරයකි",
        "ශ්‍රී ලංකාවේ 1:50,000 සිතියම්වල සමෝච්ච රේඛා මීටර් 20 පරතරයෙන් අඳිනු ලැබේ."),
      q(t, "භූලක්ෂණ සිතියමක ජලාශ, ගංගා, ඇළ දොළ සහ කලපු නිරූපණය කිරීමට භාවිත කරන සම්මත වර්ණය කුමක්ද?",
        "ජලවහන ලක්ෂණ දැක්වෙන නිල් පැහැය", "භූ විෂමතාව දැක්වෙන දුඹුරු පැහැය", "වෘක්ෂලතා දැක්වෙන කොළ පැහැය", "ප්‍රධාන මාර්ග දැක්වෙන රතු පැහැය",
        "ජල වහන ලක්ෂණ (Drainage features) සැමවිටම නිල් පැහැයෙන් දක්වයි."),
      q(t, "සම්මත භූලක්ෂණ සිතියම්වල සමෝච්ච රේඛා සහ උන්නතාංශ අගයන් දැක්වීමට යොදන වර්ණය කුමක්ද?",
        "භූ විෂමතාව සඳහා යොදන දුඹුරු පැහැය", "මහාමාර්ග සඳහා යොදන රතු පැහැය", "ජල මාර්ග සඳහා යොදන නිල් පැහැය", "ගොඩනැගිලි සඳහා යොදන කළු පැහැය",
        "භූ විෂමතාව හා සමෝච්ච රේඛා දැක්වීම සඳහා දුඹුරු වර්ණය යොදා ගැනේ."),
      q(t, "භූලක්ෂණ සිතියමක ස්වාභාවික වනාන්තර, කඩොලාන හා වගාබිම් දැක්වීමට යොදාගන්නා ප්‍රධාන වර්ණය කුමක්ද?",
        "වෘක්ෂලතා නිරූපණය කරන කොළ පැහැය", "උන්නතාංශ නිරූපණය කරන දුඹුරු පැහැය", "පරිපාලන සීමා නිරූපණය කරන කළු පැහැය", "ප්‍රවාහන මාර්ග නිරූපණය කරන රතු පැහැය",
        "වෘක්ෂලතා හා කෘෂිකාර්මික ඉඩම් කොළ පැහැති සංකේත මඟින් නිරූපණය කෙරේ."),
      q(t, "සිතියමක ප්‍රධාන මහාමාර්ග (A ශ්‍රේණියේ මාර්ග) සහ නාගරික මාර්ග දැක්වීමට බහුලව භාවිත කරන වර්ණය කුමක්ද?",
        "තද රතු පැහැති රේඛා සංකේතය", "තද නිල් පැහැති රේඛා සංකේතය", "ලා කොළ පැහැති රේඛා සංකේතය", "සිහින් දුඹුරු පැහැති රේඛා සංකේතය",
        "ප්‍රධාන ප්‍රවාහන මාර්ග රතු වර්ණයෙන් ද දුම්රිය මාර්ග කළු වර්ණයෙන් ද දැක්වේ."),
      q(t, "භූලක්ෂණ සිතියමක පිහිටීමක් ඉතා නිවැරදිව මීටර් 100 ක් ඇතුළත හඳුනා ගැනීම සඳහා භාවිත කරන ඛණ්ඩාංක ක්‍රමය කුමක්ද?",
        "අංක හයේ ඛණ්ඩාංක ක්‍රමය (6-figure)", "අංක හතරේ ඛණ්ඩාංක ක්‍රමය (4-figure)", "අංක දෙකේ ඛණ්ඩාංක ක්‍රමය (2-figure)", "සාමාන්‍ය අක්ෂාංශ දේශාංශ ක්‍රමය",
        "අංක 6 ඛණ්ඩාංකය මඟින් කි.මී. 1x1 කොටුව 100m x 100m කුඩා කොටු 100 කට බෙදා නිශ්චිත ස්ථානය දක්වයි."),
      q(t, "සිතියම් ඛණ්ඩාංකයක් (Grid Reference) කියවීමේදී පළමුවෙන්ම කියවිය යුත්තේ කුමන රේඛා අගයද?",
        "සිරස්ව පිහිටි නැගෙනහිර රේඛා අගය (Eastings)", "තිරස්ව පිහිටි උතුරු රේඛා අගය (Northings)", "බෑවුම් දක්වන සමෝච්ච රේඛා අගය", "වේලා කලාප දක්වන දේශාංශ රේඛා අගය",
        "ඛණ්ඩාංක කියවීමේ මූලික රීතිය 'පළමුව Eastings (සිරස් රේඛා), දෙවනුව Northings (තිරස් රේඛා)' යන්නයි."),
      q(t, "සමෝච්ච රේඛා පහළ බිම දෙසට නෙරා යන 'U' හෝ 'V' හැඩැති ආරුක්කුවක් ලෙස පිහිටීමෙන් දැක්වෙන භූ ලක්ෂණය කුමක්ද?",
        "පහළට විහිදුණු කඳු නෙරුවක් (Spur)", "ගංගාවක් ගලන ගැඹුරු නිම්නයක් (Valley)", "හුදෙකලා වටකුරු කඳු ගැටයක් (Knoll)", "කඳු මුදුන් අතර කපොල්ලක් (Col)",
        "V අකුරේ තුඩ පහළ උන්නතාංශය දෙසට යොමු වූ විට කඳු නෙරුවක් (Spur) ද, ඉහළට යොමු වූ විට නිම්නයක් ද දැක්වේ."),
      q(t, "සමෝච්ච රේඛා ඉහළ උන්නතාංශ දෙසට 'V' හැඩයෙන් නැමී තිබෙන තැන්හි බොහෝ විට ගලා බසින ලක්ෂණය කුමක්ද?",
        "නිම්නයක් තුළින් ගලන ගංගාවක් හෝ දොළ පහරක්", "ප්‍රපාතාකාර බෑවුමක පිහිටි උස් කඳු වැටියක්", "වෙරළාසන්න වැලි වැටියකින් වෙන් වූ කලපුවක්", "තැනිතලා ප්‍රදේශයක පිහිටි වියළි සානුවක්",
        "ඉහළ උන්නතාංශ දෙසට නැමුණු V රේඛා මඟින් ගංගා නිම්න නිරූපණය කෙරේ."),
      q(t, "ඉහළ කොටසේ සමෝච්ච රේඛා ඉතා සමීපව පිහිටා, පහළ කොටසේ රේඛා ඈතින් පිහිටා ඇති බෑවුම කුමන ආකාරයේ බෑවුමක්ද?",
        "ඉහළින් තද හා පහළින් මෘදු අවතල බෑවුම", "ඉහළින් මෘදු හා පහළින් තද උත්තල බෑවුම", "සෑම තැනම සමාන පරතරයක් ඇති ඒකාකාර බෑවුම", "පඩිපෙළක් ලෙස පිහිටි සෝපානමය බෑවුම",
        "ඉහළ තද බෑවුමක් (ළං වූ රේඛා) හා පහළ මෘදු බෑවුමක් (ඈත් වූ රේඛා) ඇති විට අවතල බෑවුමක් සෑදේ."),
      q(t, "ඉහළ කොටසේ සමෝච්ච රේඛා ඈතින් පිහිටා පහළට යත්ම ඉතා ළං වී පිහිටන්නේ නම් එම බෑවුම කුමක්ද?",
        "මුදුන මෘදු හා පාමුල තද උත්තල බෑවුම", "මුදුන තද හා පාමුල මෘදු අවතල බෑවුම", "උසින් නොවෙනස් වන සමතලා තැනිතලාව", "සමාන පරතරයක් ඇති ඒකාකාර බෑවුම",
        "උත්තල බෑවුමේදී මුදුන මෘදු වී පාමුල තීව්‍ර වන අතර අන්තර් දර්ශනය (Intervisibility) බාධා විය හැකිය."),
      q(t, "සමෝච්ච රේඛා එකිනෙක මත ගොඩගැසී තනි රේඛාවක් මෙන් දිස්වන සිතියම් ස්ථානයකින් පෙනෙන භූ ලක්ෂණය කුමක්ද?",
        "සිරස් ප්‍රපාතයක් හෝ උස් දිය ඇල්ලක්", "ඉතා පුළුල් මෘදු ගංගා නිම්නයක්", "අවම බෑවුමක් සහිත වෙරළ තැනිතලාවක්", "කඳු මුදුන් දෙකක් අතර පිහිටි කපොල්ලක්",
        "සමෝච්ච රේඛා එක මත එක පිහිටීමෙන් සිරස් බෑවුමක් හෙවත් ප්‍රපාතයක් නිරූපණය වේ."),
      q(t, "කඳු මුදුන් දෙකක් අතර පිහිටි පහත් අවපාත කොටස භූලක්ෂණ සිතියමක හඳුන්වන්නේ කුමන නමින්ද?",
        "කඳු කපොල්ල හෝ සෑදලය (Col / Saddle)", "හුදෙකලා කේතුකාකාර කන්ද (Conical Hill)", "සිරස් ප්‍රපාතාකාර කඳු බෑවුම (Cliff)", "දිගටි කඳු වැටි නෙරුව (Spur)",
        "කඳු දෙකක් අතර මාර්ග ඉදිකිරීමට යොදාගන්නා පහත් ස්ථාන සෑදල හෝ කපොලු ලෙස හැඳින්වේ."),
      q(t, "මධ්‍යය ඉතා පැතලි හා පුළුල් වී වටපිටාවේ සමෝච්ච රේඛා ඉතා සමීපව බෑවුම් වන උස් භූමි රූපය කුමක්ද?",
        "වටේ තද බෑවුම් සහිත උස් සානුව (Plateau)", "ඉහළට උල් වූ කේතුකාකාර කන්ද", "ඉහළට නැමුණු V හැඩැති ගංගා නිම්නය", "මුහුදු වෙරළ දෙසට ඇති කුඩා නෙරුව",
        "වටේ තද බෑවුම් හා මැද පැතලි උස් බිමක් තිබීම සානුවක සමෝච්ච ලක්ෂණයයි."),
      q(t, "ඒක කේන්ද්‍රීය වෘත්තාකාර සමෝච්ච රේඛා මැදට යත්ම අගයන් වැඩි වන්නේ නම් ඉන් නිරූපණය වන්නේ කුමක්ද?",
        "වටකුරු කේතුකාකාර කඳු ගැටයක්", "ඇතුළට ගිලුණු වළක් හෝ ආවාටයක්", "පුළුල් ගංගා පිටාර තැනිතලාවක්", "දෙපසට විහිදුණු ගැඹුරු නිම්නයක්",
        "මධ්‍යය දෙසට උන්නතාංශ අගය ඉහළ යන ඒක කේන්ද්‍රීය රේඛා කඳු ගැටයක් පෙන්වයි."),
      q(t, "ප්‍රධාන ශාඛා ගංගාවට කුඩා අතු ගංගා ගසක අතු බෙදෙන ආකාරයෙන් එකතු වන ජලවහන රටාව කුමක්ද?",
        "ගසක අතු මෙන් විහිදෙන ද්‍රැම රූපී රටාව", "මධ්‍ය කන්දකින් විහිදෙන අරීය රටාව", "සෘජුකෝණාකාරව එක්වන ජාලාකාර රටාව", "මැද විලකට ගලන අභිකේන්ද්‍ර රටාව",
        "ඒකාකාර පාෂාණ සැකැස්මක් ඇති බිමක ගසක අතු මෙන් විහිදෙන රටාව ද්‍රැම රූපී රටාවයි."),
      q(t, "ශ්‍රී ලංකාවේ මධ්‍යම කඳුකරයේ සිට හතර දිසාවටම ගංගා ගලා බැසීම කුමන ජලවහන රටාවට හොඳම නිදසුනක්ද?",
        "මධ්‍ය කඳුකරයෙන් විහිදෙන අරීය ජලවහන රටාව", "මධ්‍ය ද්‍රෝණියකට එක්වන අභිකේන්ද්‍ර ජලවහන රටාව", "සමාන්තර කඳු අතර දිවෙන ජාලාකාර ජලවහන රටාව", "තැනිතලාවේ සෑදෙන ද්‍රැම රූපී ජලවහන රටාව",
        "උස් කේතුකාකාර කඳු මුදුනක හෝ ගෝලාකාර උස්බිමක සිට සිව්දෙසට ගංගා විහිදීම අරීය රටාවයි."),
      q(t, "අතු ගංගා ප්‍රධාන ගංගාවට සෘජුකෝණාකාරව (90° ට ආසන්නව) සම්බන්ධ වන රටාව කුමක්ද?",
        "ජාලාකාර හෝ සෘජුකෝණී ජලවහන රටාව", "කඳු මුදුනකින් විහිදෙන අරීය ජලවහන රටාව", "පහත් ද්‍රෝණියකට ගලන අභිකේන්ද්‍ර රටාව", "ඒකාකාර බෑවුමක ද්‍රැම රූපී රටාව",
        "මෘදු හා දෘඪ පාෂාණ ස්ථර මාරුවෙන් මාරුවට පිහිටි නැමි බිම්වල ජාලාකාර රටාව සෑදේ."),
      q(t, "කඳු ගැටවලින් වටවූ මධ්‍යගත අවපාතයකට හෝ වැවකට සිව්දෙසින් දිය පහරවල් ගලා එන රටාව කුමක්ද?",
        "මධ්‍යයට එක්රැස් වන අභිකේන්ද්‍ර ජලවහන රටාව", "කඳු මුදුනින් පිටතට යන අරීය ජලවහන රටාව", "ඒකාකාර බිමේ සෑදෙන ද්‍රැම රූපී රටාව", "බෑවුම දිගේ පහළට ගලන සමාන්තර රටාව",
        "මධ්‍යයෙහි පිහිටි විලක් හෝ ද්‍රෝණියක් දෙසට ජලය එක්රැස් වීම අභිකේන්ද්‍ර රටාවයි."),
      q(t, "සිතියමක 'ස්ථාන දෙකක් අතර අන්තර් දර්ශනය' (Intervisibility) පරීක්ෂා කිරීම සඳහා ප්‍රධාන වශයෙන් අඳින්නේ කුමක්ද?",
        "සමෝච්ච රේඛා ඇසුරින් අඳින හරස්කඩ සටහනක්", "ජනගහන අනුපාත දැක්වෙන වෘත්ත ප්‍රස්තාරයක්", "වර්ෂාපතන රටාව දැක්වෙන තීරු ප්‍රස්තාරයක්", "භාණ්ඩ ප්‍රවාහනය දැක්වෙන ප්‍රවාහ සිතියමක්",
        "සමෝච්ච රේඛා ඇසුරින් අඳින හරස්කඩ මඟින් ස්ථාන දෙක අතර උස් බාධක ඇත්දැයි බලා ගත හැකිය."),
      q(t, "සිතියමේ ස්ථානයක නිවැරදි මුහුදු මට්ටමේ සිට උස පෙන්නුම් කරන 'BM 142.5' යන සංකේතයේ අර්ථය කුමක්ද?",
        "මීටර් 142.5 ක් උස ස්ථිර මිනුම් සලකුණකි", "මීටර් 142.5 ක් දිග ප්‍රධාන මාර්ග පාලමකි", "වර්ග කිලෝමීටර් 142.5 ක වන රක්ෂිත කලාපයකි", "මීටර් 142.5 ක් ගැඹුරු භූගත ජල මට්ටමකි",
        "Bench Mark යනු ස්ථිර ගොඩනැගිල්ලක හෝ පාෂාණයක සටහන් කළ නිශ්චිත උන්නතාංශයයි."),
      q(t, "භූලක්ෂණ සිතියමක කුඩා ත්‍රිකෝණයක් අසල '△ 842' ලෙස සඳහන් කර ඇති විට ඉන් අදහස් වන්නේ කුමක්ද?",
        "මීටර් 842 ක් උස ත්‍රිකෝණමිතික මිනුම් ස්ථානයකි", "මීටර් 842 ක් පළල සක්‍රීය ගිනි කඳු ආවාටයකි", "මීටර් 842 ක් දිග දුම්රිය උමං මාර්ගයකි", "මීටර් 842 ක් උස ජලාශ වේල්ලක බැම්මකි",
        "මිනින්දෝරු කටයුතුවලදී නිවැරදිම උස මැන ස්ථාපිත කළ කඳු මුදුන් ත්‍රිකෝණ සලකුණෙන් දක්වයි."),
      q(t, "කළු තිතක් අසල '. 315' ලෙස සඳහන් කර ඇති සිතියම් උන්නතාංශ ක්‍රමය කුමක්ද?",
        "විශේෂිත ස්ථානයක උස දක්වන ස්ථානීය උස", "පාලමක හෝ බැම්මක ස්ථිර මිනුම් සලකුණ", "සමාන උස යා කරන සමෝච්ච රේඛාව", "බෑවුම් දිශාව පෙන්වන හැෂුවර් රේඛාව",
        "සමෝච්ච රේඛාවලට අමතරව විශේෂිත තැනක උස දැක්වීමට Spot Height (.315) භාවිත කෙරේ."),
      q(t, "මාලිමා යන්ත්‍රයකින් මැන ගන්නා උතුරු දිශාව සහ සිතියමේ භූගෝලීය උතුරු දිශාව අතර පවතින වෙනස කුමක්ද?",
        "සත්‍ය හා චුම්බක උතුර අතර චුම්බක අපගමනය", "නැගෙනහිර හා බටහිර අතර අක්ෂාංශ අන්තරය", "සිතියම් ඇඳීමේදී ඇතිවන පරිමාණ විකෘති දෝෂය", "පෘථිවි භ්‍රමණයෙන් ඇතිවන කෝරියෝලිස් ආචරණය",
        "සත්‍ය උතුර (True North) හා චුම්බක උතුර (Magnetic North) අතර කෝණික වෙනස චුම්බක අපගමනයයි."),
      q(t, "සැබෑ උතුරේ සිට ඔරලෝසු කටුව ගමන් කරන දිශාවට (දක්ෂිණාවර්තව) මනිනු ලබන කෝණය හඳුන්වන්නේ කුමන නමින්ද?",
        "දිශා කෝණය හෙවත් බෙයාරිම (Bearing)", "සමකයේ සිට මනිනු ලබන අක්ෂාංශ අගය", "බෑවුමේ තීව්‍රතාව දක්වන අනුක්‍රමණය (Gradient)", "පෘථිවි අක්ෂයේ ඇලවීම දක්වන ආනති කෝණය",
        "0° සිට 360° දක්වා දක්ෂිණාවර්තව මනින දිශා කෝණය බෙයාරිම නම් වේ."),
      q(t, "'ඊසාන' (North-East) දිශාව සම්පූර්ණ වෘත්ත බෙයාරිම් කෝණයෙන් (Whole Circle Bearing) කීයද?",
        "උතුරට හා නැගෙනහිරට මැද 045° කෝණය", "සෘජුවම නැගෙනහිර දෙසට 090° කෝණය", "නැගෙනහිර හා දකුණ අතර 135° කෝණය", "බටහිර හා උතුර අතර 315° කෝණය",
        "උතුර 000° හා නැගෙනහිර 090° අතර මධ්‍යය වන ඊසාන දිශාව 045° කි."),
      q(t, "'නිරිත' (South-West) දිශාවේ සම්පූර්ණ වෘත්ත බෙයාරිම් අගය අංශක කීයද?",
        "දකුණ හා බටහිර අතර 225° කෝණය", "නැගෙනහිර හා දකුණ අතර 135° කෝණය", "සෘජුවම බටහිර දෙසට යොමු වූ 270° කෝණය", "බටහිර හා උතුර අතර 315° කෝණය",
        "දකුණ 180° සහ බටහිර 270° අතර මැද පිහිටි නිරිත දිශාව 225° කි."),
      q(t, "එක් පරිපාලන ඒකකයක (උදාහරණ ලෙස දිස්ත්‍රික්කයක) ජන ඝනත්වය වැනි සාමාන්‍ය අගයන් වර්ණ පරාස මඟින් දක්වන තේමා සිතියම කුමක්ද?",
        "වර්ණ මට්ටම් යොදන වර්ණ කලාප සිතියම", "නිශ්චිත අගයක් පෙන්වන තිත් සිතියම", "සමාන අගයන් යා කරන සමරේඛා සිතියම", "චලන පරිමාව පෙන්වන ප්‍රවාහ සිතියම",
        "පරිපාලන සීමා අනුව අගයන් විවිධ වර්ණ හෝ සෙවණැලි මට්ටම්වලින් දැක්වීම Choropleth සිතියමේ ලක්ෂණයයි."),
      q(t, "භාණ්ඩ ප්‍රවාහන පරිමාව, සංචාරක ගමන් මාර්ග හෝ සංක්‍රමණ දිශාවන් රේඛාවල පළල අනුව දක්වන සිතියම් වර්ගය කුමක්ද?",
        "පළල වෙනස් වන රේඛා සහිත ප්‍රවාහ සිතියම", "ව්‍යාප්තිය තිත් මඟින් පෙන්වන තිත් සිතියම", "සීමා තුළ වර්ණ යොදන වර්ණ කලාප සිතියම", "උන්නතාංශ රේඛා පෙන්වන සමෝච්ච සිතියම",
        "ගමන් කරන ප්‍රමාණයට අනුපාතිකව රේඛාවල ඝනකම වෙනස් කරමින් ප්‍රවාහ සිතියම් අඳියි."),
      q(t, "එක් තිතකින් නිශ්චිත ප්‍රමාණයක් (උදාහරණ ලෙස පුද්ගලයන් 5,000ක්) නිරූපණය කරමින් ව්‍යාප්තිය පෙන්වන සිතියම් වර්ගය කුමක්ද?",
        "ප්‍රමාණාත්මක තිත් සංකේත යොදන තිත් සිතියම", "ගමන් මාර්ග පෙන්වන ප්‍රවාහ රේඛා සිතියම", "පරිපාලන වර්ණ යොදන වර්ණ කලාප සිතියම", "පාෂාණ ස්තර දැක්වෙන භූ විද්‍යා සිතියම",
        "ජනගහනය හෝ බෝග ව්‍යාප්තිය ස්ථානගතව පෙන්වීමට තිත් සිතියම් ඉතා සුදුසුය."),
      q(t, "සමාන වටිනාකමක් ඇති ස්ථාන යා කරමින් (උදාහරණ ලෙස සම වර්ෂා, සම උෂ්ණත්ව) අඳිනු ලබන සිතියම් වර්ගය කුමක්ද?",
        "සමාන අගයන් යා කරන සමරේඛා සිතියම", "ජන ඝනත්වය දැක්වෙන තිත් ව්‍යාප්ති සිතියම", "පරිපාලන දිස්ත්‍රික් දැක්වෙන වර්ණ කලාප සිතියම", "රාජ්‍ය සීමා පෙන්වන දේශපාලන සිතියම",
        "අඛණ්ඩව වෙනස් වන උෂ්ණත්වය, පීඩනය හෝ උස වැනි දත්ත සමරේඛා මඟින් නිරූපණය කෙරේ."),
      q(t, "භූගෝලීය තොරතුරු පද්ධති (GIS) තුළ 'ලක්ෂ්‍ය, රේඛා සහ බහුඅස්‍ර' ලෙස දත්ත ගබඩා කරන ආකෘතිය කුමක්ද?",
        "ඛණ්ඩාංක පාදක දෛශික දත්ත ආකෘතිය (Vector)", "කුඩා කොටු පාදක රාස්ටර් දත්ත ආකෘතිය (Raster)", "සංඛ්‍යාලේඛන පමණක් ඇති වගු දත්ත ආකෘතිය", "කඩදාසි මුද්‍රිත සාම්ප්‍රදායික සිතියම් ආකෘතිය",
        "නිශ්චිත ඛණ්ඩාංක ඇති ලක්ෂ්‍ය (ළිං), රේඛා (මාර්ග) හා බහුඅස්‍ර (වැව්) දෛශික දත්ත ලෙස හැඳින්වේ."),
      q(t, "චන්ද්‍රිකා ඡායාරූපවල මෙන් කුඩා සමචතුරස්‍ර කොටු (Pixels) මඟින් දත්ත දක්වන GIS ආකෘතිය කුමක්ද?",
        "පික්සල් ජාල සහිත රාස්ටර් දත්ත ආකෘතිය (Raster)", "ලක්ෂ්‍ය හා රේඛා සහිත දෛශික ආකෘතිය (Vector)", "පරිපාලන නාම ඇති ගුණාත්මක වගු ආකෘතිය", "හරස්කඩ සටහන් අඳින රේඛීය සිතියම් ආකෘතිය",
        "සෑම පික්සල් කොටුවකටම එක් අගයක් පවරා අඛණ්ඩ පෘෂ්ඨ නිරූපණය කිරීම රාස්ටර් ආකෘතියයි."),
      q(t, "ගෝලීය ස්ථානගත කිරීමේ පද්ධතියකින් (GPS) පෘථිවිය මත ස්ථානයක නිවැරදි පිහිටීම ලබා ගැනීමට අවම වශයෙන් චන්ද්‍රිකා කීයක සංඥා අවශ්‍ය වේද?",
        "අවම වශයෙන් GPS චන්ද්‍රිකා 4 ක සංඥා", "අවම වශයෙන් GPS චන්ද්‍රිකා 1 ක සංඥා", "අවම වශයෙන් GPS චන්ද්‍රිකා 2 ක සංඥා", "අවම වශයෙන් GPS චන්ද්‍රිකා 12 ක සංඥා",
        "ත්‍රිමාණ (3D) පිහිටීම හා කාල දෝෂය නිවැරදි කිරීමට අවම වශයෙන් GPS චන්ද්‍රිකා 4 ක සංඥා අවශ්‍ය වේ."),
      q(t, "භෞතික ස්පර්ශයකින් තොරව ගුවන් යානා හෝ චන්ද්‍රිකා ආධාරයෙන් පෘථිවි පෘෂ්ඨයේ තොරතුරු රැස් කිරීම හඳුන්වන්නේ කෙසේද?",
        "දුර සිට තොරතුරු ලබාගන්නා දුරස්ථ සංවේදනය", "පොළොව මත මිනුම් ගන්නා භූමි මැනුම", "විශාල සිතියම් කුඩා කරන සිතියම් සාමාන්‍යකරණය", "ගෝලය තලයකට ගන්නා සිතියම් ප්‍රක්ෂේපණය",
        "විද්‍යුත් චුම්බක තරංග පරාවර්තනය හෝ විමෝචනය මඟින් දුර සිට දත්ත ලබා ගැනීම දුරස්ථ සංවේදනයයි."),
      q(t, "පෘථිවි පෘෂ්ඨයෙන් පරාවර්තනය වන සූර්යාලෝකය මත රඳා පවතින දුරස්ථ සංවේදක උපකරණ හඳුන්වන්නේ කුමන නමින්ද?",
        "ස්වාභාවික ශක්තිය භාවිත කරන අක්‍රීය සංවේදක", "තමන්ගේම තරංග යවන සක්‍රීය සංවේදක", "මුහුදු ගැඹුර මනින සෝනාර් සංවේදක", "වර්ෂාව මනින ඩොප්ලර් රේඩාර් සංවේදක",
        "ස්වාභාවික සූර්ය ශක්තිය මත ක්‍රියා කරන සංවේදක අක්‍රීය සංවේදක වන අතර රේඩාර්/LiDAR සක්‍රීය සංවේදක වේ."),
      q(t, "වලාකුළු ආවරණය පවතින රාත්‍රී කාලයේදී පවා තමන්ගේම සංඥා නිකුත් කර පෘථිවියේ දත්ත ලබාගන්නා සංවේදක කවරේද?",
        "රේඩාර් වැනි ස්වයං-සංඥා නිකුත් කරන සක්‍රීය සංවේදක", "සූර්යාලෝකය මත යැපෙන අක්‍රීය ප්‍රකාශ සංවේදක", "දිවා කාලයේ පමණක් ක්‍රියාකරන ගුවන් කැමරා", "තාපය පමණක් සටහන් කරන භෞමික උෂ්ණත්වමාන",
        "සක්‍රීය සංවේදක තමා විසින්ම තරංග යවා ආපසු පැමිණෙන තරංග මැන ගනී."),
      q(t, "ගෝලාකාර පෘථිවි පෘෂ්ඨය පැතලි කඩදාසියක් මත ඇඳීමේදී භාවිත කරන ගණිතමය ක්‍රමවේදය හඳුන්වන්නේ කුමන නමින්ද?",
        "ගෝලීය පෘෂ්ඨ තලයකට හරවන සිතියම් ප්‍රක්ෂේපණය", "සමෝච්ච රේඛා අතර උස ගණනය කිරීම", "කිලෝමීටර් කොටු බෙදීමේ සිතියම් ජාලකරණය", "භූමි මැනුමේදී යොදාගන්නා මැනුම් ත්‍රිකෝණකරණය",
        "ත්‍රිමාණ ගෝලයක් ද්විමාන තලයකට පරිවර්තනය කිරීමේදී සිතියම් ප්‍රක්ෂේපණ භාවිත වේ."),
      q(t, "ධ්‍රැව ආසන්න ප්‍රදේශවල වර්ගඵලය විශාල කර පෙන්නුවද, නාවික ගමන් මාර්ග සඳහා නිවැරදි දිශාවන් පවත්වා ගන්නා ප්‍රක්ෂේපණය කුමක්ද?",
